public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long r = scanner.nextLong();
        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long xp = scanner.nextLong();
        long yp = scanner.nextLong();

        long dx = xp - x;
        long dy = yp - y;
        long distSq = dx * dx + dy * dy;

        if (distSq == 0) {
            System.out.println(0);
            return;
        }

        long stepLen = 2 * r;
        long stepLenSq = stepLen * stepLen;

        long k = (long) Math.sqrt(distSq);
        while (k * k < distSq) k++;
        while (k > 0 && (k - 1) * (k - 1) >= distSq) k--;

        if (k % stepLen == 0) {
            System.out.println(k / stepLen);
        } else {
            System.out.println(k / stepLen + 1);
        }
    }
}
